<x-layouts.app title="Cocina y despacho"><div x-data="{refresh:true}" x-init="setInterval(()=>{ if(refresh && !document.querySelector('select:focus,input:focus,textarea:focus')) window.location.reload() },30000)"><div class="page-heading"><div><span class="eyebrow">MONITOR DE PRODUCCIÓN</span><h1>Cocina y despacho</h1><p class="muted">Pedidos activos ordenados por fecha y hora de entrega.</p></div><label class="check-label"><input type="checkbox" x-model="refresh"> Actualizar cada 30 s</label></div><div class="kds-grid">@foreach(['pendiente'=>'Pendientes','en_preparacion'=>'En preparación','listo'=>'Listos','en_ruta'=>'En ruta'] as $state=>$label)<section class="kds-column"><h2>{{ $label }} <span class="tag">{{ $orders->where('status',$state)->count() }}</span></h2>@forelse($orders->where('status',$state) as $o)<article class="kds-card"><div class="row-between"><b>{{ $o->scheduled_date->format('d/m') }} · {{ substr($o->scheduled_time,0,5) }}</b><span class="tag">{{ $o->delivery_type }}</span></div><h3><a href="{{ route('orders.show',$o) }}">{{ $o->customer_name }}</a></h3><small class="muted">Folio {{ $o->order_number }}</small><ul>@foreach($o->items->where('is_cancelled',false) as $i)<li><b>{{ $i->quantity }} ×</b> {{ $i->product_name }}
